#ifndef PICA_CODEC_TABLES_H
#define PICA_CODEC_TABLES_H

#include "etypes.h"

struct SbcsTable {
  u16 cp;            // Windows code page number
  u16 nrev;          // entries in rev_cp / rev_b (= defined high bytes)
  const u16* hi;     // decode of bytes 0x80-0xFF; 0 = undefined byte (decodes to ECP_BADBYTE)
  const u16* rev_cp; // code points of the defined high bytes, sorted ascending (all >= 0x80)
  const u8*  rev_b;  // byte for rev_cp[i]
};
extern const SbcsTable g_sbcs_tables[];
extern const u32 g_sbcs_table_count;

#endif
